    def extract_fruits_count(s):
        apples, oranges = s.split(" and ")
        apples = int(apples.split()[0])
        oranges = int(oranges.split()[0])
        return apples, oranges

    def calculate_mangoes(s, n):
        apples, oranges = extract_fruits_count(s)
        total_fruits = apples + oranges
        mangoes = n - total_fruits
        return mangoes

    return calculate_mangoes(s, n)

